def chegada(codigo, continente, lon, lat):
    """(região, quando os sapiens chegaram a este ponto em Ma)."""
    for regiao, codigos, caixa, idade in CHEGADA:
        if codigos and codigo not in codigos:
            continue
        if caixa and not (caixa[0] <= lon <= caixa[1] and caixa[2] <= lat <= caixa[3]):
            continue
        return regiao, idade
    if continente == "Africa":
        # origem pan-africana: desde Jebel Irhoud (~315 mil anos) há sapiens por todo o continente
        return "africa", 0.315
    if continente == "Antarctica":
        return "antartida", A(1900)
    return "outros", 0.045


